// Charts for the benchmark appendix of "Which codebase would an LLM rather maintain?".
// Each <figure class="bb-chart" data-draw="..."> in the post is filled from data.json. Needs d3, loaded before this file.
// Generated by report/blog_export.py in the benchmark folder from the report page; edit there, not here.
(function () {
  const HERE = document.currentScript.src;
  let DATA = null;
  const draws = {};
  const dash = {
    draw: (name, fn) => { draws[name] = fn; },
    data: (id) => DATA && DATA[id] ? {status: 'ok', data: DATA[id]} : {status: DATA ? 'error' : 'loading', data: []},
  };

  const ARMS = ['baseline', 'ponytail', 'ponytail-anchor', 'ken', 'bunnyhug-v8'];
  const OPEN = () => false;   // an earlier revision shown beside a later one would be drawn open (hollow dots, dashed line, lighter bar); only one is shown
  const MODEL = {haiku: 'Haiku', sonnet: 'Sonnet', opus: 'Opus'};
  const FAM = {Bunnyhug: 'var(--bb-bunnyhug)', Ponytail: 'var(--bb-ponytail)', Ken: 'var(--bb-ken)', Baseline: 'var(--bb-baseline)'};
  const SURFACE = 'var(--bb-surface)';
  const trim = (v) => String(+v.toPrecision(3));
  const FMT = {
    int: d3.format(',.0f'), d1: d3.format(',.1f'), d2: d3.format('.2f'),
    usd2: (v) => '$' + d3.format(',.2f')(v), usd4: (v) => '$' + d3.format('.4f')(v),
    pct: (v) => d3.format('.1f')(v) + '%', pct0: (v) => d3.format('.0f')(v) + '%', text: (v) => String(v),
  };
  const usdTick = (v) => '$' + trim(v), pctTick = (v) => trim(v) + '%';
  const perRun = (fmt) => (g) => g.map((r) => 'Run ' + (r.seq + 1) + ': ' + fmt(r));

  // twenty dots in a row: the value column gives the median, and hover gives the spread
  const many = (fmt, field) => ({many: true, val: (g) => 'median ' + fmt(d3.median(g, (r) => r[field])),
    tip: (g) => [g.length + ' runs', 'lowest ' + fmt(d3.min(g, (r) => r[field])) + ', highest ' + fmt(d3.max(g, (r) => r[field]))]});
  const SCORE_OPACITY = [0.22, 0.55, 0.8, 1];
  const CHARTS = {
    'h20-cost': {src: 'haiku20', field: 'cost_usd', fmt: FMT.usd2, tick: usdTick, facets: ['haiku'], dots: true, label: 'Cost of all eleven tickets', ...many(FMT.usd2, 'cost_usd')},
    'h20-late': {src: 'haiku20', field: 'late_cost_usd', fmt: FMT.usd2, tick: usdTick, facets: ['haiku'], dots: true, label: 'Cost of tickets 7 to 11', ...many(FMT.usd2, 'late_cost_usd')},
    'h20-rule': {src: 'haiku20', field: 'rule_ticket_lines_changed', fmt: FMT.int, tick: FMT.int, facets: ['haiku'], dots: true, label: 'Lines changed by the rule ticket', ...many(FMT.int, 'rule_ticket_lines_changed')},
    'h20-feature': {src: 'haiku20', field: 'feature_ticket_lines_changed', fmt: FMT.int, tick: FMT.int, facets: ['haiku'], dots: true, label: 'Lines changed by the feature ticket', ...many(FMT.int, 'feature_ticket_lines_changed')},
    'h20-shared': {src: 'haiku20', field: 'shared_lines', fmt: FMT.int, tick: FMT.int, facets: ['haiku'], dots: true, label: 'Lines the browser shares with the server and library', ...many(FMT.int, 'shared_lines')},
    'h20-lines': {src: 'haiku20', field: 'source_lines', fmt: FMT.int, tick: FMT.int, facets: ['haiku'], dots: true, label: 'Source lines after eleven tickets', ...many(FMT.int, 'source_lines')},
    'h20-files': {src: 'haiku20', field: 'rule_files', fmt: FMT.d1, tick: FMT.int, facets: ['haiku'], dots: true, label: 'Files holding the five rules', ...many((v) => String(+v.toFixed(1)), 'rule_files')},
    'h20-share': {src: 'haiku20', field: 'share_behind_library_pct', fmt: FMT.pct, tick: pctTick, facets: ['haiku'], dots: true, label: 'Share of source lines behind the library', ...many(FMT.pct0, 'share_behind_library_pct')},
    'h20-survival': {src: 'haiku20', field: 'test_survival_pct', fmt: FMT.pct, tick: pctTick, facets: ['haiku'], dots: true, min: 80, max: 100, label: 'Old tests still passing after the next ticket', ...many(FMT.pct, 'test_survival_pct')},
    'seq-cost': {src: 'sequences', field: 'cost_usd', fmt: FMT.usd2, tick: usdTick, facets: ['opus'], dots: true, label: 'Cost of all eleven tickets',
      tip: perRun((r) => FMT.usd2(r.cost_usd) + ', ' + r.minutes + ' min')},
    'seq-lines': {src: 'sequences', field: 'source_lines', fmt: FMT.int, tick: FMT.int, facets: ['opus'], dots: true, shared: true, label: 'Source lines after the last ticket',
      tip: perRun((r) => FMT.int(r.source_lines) + ' source lines, ' + FMT.int(r.test_lines) + ' test lines')},
    'seq-files': {src: 'sequences', field: 'rule_files', fmt: (v) => String(+v.toFixed(1)), tick: FMT.int, facets: ['opus'], dots: true, shared: true, label: 'Files holding the five rules',
      tip: perRun((r) => r.rule_files + ' files; blank-text rule in ' + r.blank_text_files + ', indent and outdent in ' + r.indent_outdent_files)},
    'seq-share': {src: 'sequences', field: 'share_behind_library_pct', fmt: FMT.pct, tick: pctTick, facets: ['opus'], dots: true, shared: true, label: 'Share of source lines behind the library',
      tip: perRun((r) => FMT.int(r.lines_behind_library) + ' of ' + FMT.int(r.source_lines) + ' lines')},
    'seq-browser': {src: 'sequences', field: 'library_lines_shared_with_browser', fmt: FMT.int, tick: FMT.int, facets: ['opus'], dots: true, shared: true, label: 'Library lines the browser also uses',
      tip: perRun((r) => FMT.int(r.library_lines_shared_with_browser) + ' of ' + FMT.int(r.lines_behind_library) + ' library lines')},
    'seq-early': {src: 'sequences', field: 'early_cost_usd', fmt: FMT.usd2, tick: usdTick, facets: ['opus'], dots: true, label: 'Cost of tickets 1 to 6',
      tip: perRun((r) => FMT.usd2(r.early_cost_usd) + ' of ' + FMT.usd2(r.cost_usd) + ' for all eleven')},
    'seq-late': {src: 'sequences', field: 'late_cost_usd', fmt: FMT.usd2, tick: usdTick, facets: ['opus'], dots: true, label: 'Cost of tickets 7 to 11',
      tip: perRun((r) => FMT.usd2(r.late_cost_usd) + ' of ' + FMT.usd2(r.cost_usd) + ' for all eleven')},
    'seq-rule': {src: 'sequences', field: 'rule_ticket_lines_changed', fmt: FMT.int, tick: FMT.int, facets: ['opus'], dots: true, shared: true, label: 'Lines changed by the rule ticket',
      tip: perRun((r) => r.rule_ticket_lines_changed + ' lines changed in ' + r.rule_ticket_files_touched + ' files, ' + FMT.usd2(r.rule_ticket_cost_usd))},
    'seq-feature': {src: 'sequences', field: 'feature_ticket_lines_changed', fmt: FMT.int, tick: FMT.int, facets: ['opus'], dots: true, shared: true, label: 'Lines changed by the feature ticket',
      tip: perRun((r) => r.feature_ticket_lines_changed + ' lines changed in ' + r.feature_ticket_files_touched + ' files, ' + FMT.usd2(r.feature_ticket_cost_usd))},
    'arm-survival': {src: 'arms', field: 'test_survival_pct', fmt: FMT.pct, tick: pctTick, facets: ['opus'], shared: true, max: 100, label: 'Old tests still passing after the next ticket',
      tip: (g) => g.map((r) => FMT.int(r.old_tests_still_passing) + ' of ' + FMT.int(r.old_tests) + ' old tests still passed')},
    'one-lines': {src: 'single_tasks', field: 'source_lines', fmt: FMT.d1, tick: FMT.int, facets: ['haiku', 'opus'], shared: true, label: 'Source lines per session',
      tip: (g) => g.map((r) => r.sessions + ' sessions, ' + r.wrote_tests_pct + '% of them wrote tests')},
    'one-cost': {src: 'single_tasks', field: 'cost_usd', fmt: FMT.usd4, tick: usdTick, facets: ['haiku', 'opus'], label: 'Cost per session',
      tip: (g) => g.map((r) => r.sessions + ' sessions, ' + FMT.d1(r.seconds) + ' seconds each')},
  };

  function wait(el, status) {
    const p = document.createElement('p');
    p.className = 'bb-wait';
    p.textContent = status === 'error' ? 'This part did not load.' : '—';
    el.replaceChildren(p);
  }
  function textW(svg, str, cls) {
    const t = svg.append('text').attr('class', cls || null).text(str);
    const w = t.node().getComputedTextLength() || String(str).length * 6.8;
    t.remove();
    return w;
  }
  function makeTip(el) {
    const tip = document.createElement('div');
    tip.className = 'bb-tip';
    tip.hidden = true;
    el.appendChild(tip);
    return {
      show(ev, title, lines) {
        tip.replaceChildren();
        const h = document.createElement('div'); h.className = 'bb-tip-title'; h.textContent = title; tip.appendChild(h);
        lines.forEach((ln) => {
          const d = document.createElement('div'); d.className = 'bb-tip-line';
          if (ln.color) { const s = document.createElement('i'); s.className = 'bb-sw'; s.style.background = ln.color; d.appendChild(s); }
          d.appendChild(document.createTextNode(ln.text || ln));
          tip.appendChild(d);
        });
        tip.hidden = false;
        const b = el.getBoundingClientRect();
        const left = Math.max(0, Math.min(ev.clientX - b.left + 14, b.width - tip.offsetWidth - 2));
        tip.style.left = left + 'px';
        tip.style.top = (ev.clientY - b.top + 18) + 'px';
      },
      hide() { tip.hidden = true; },
    };
  }
  const bar = (x0, x1, y, h, r) => { r = Math.min(r, Math.max(0, x1 - x0)); return 'M' + x0 + ',' + y + 'H' + (x1 - r) + 'a' + r + ',' + r + ' 0 0 1 ' + r + ',' + r + 'V' + (y + h - r) + 'a' + r + ',' + r + ' 0 0 1 ' + (-r) + ',' + r + 'H' + x0 + 'Z'; };

  // one row per contender; dots (one per run) or a bar (one value), a facet per model
  dash.draw('rows', (el) => {
    const cfg = CHARTS[el.dataset.chart];
    if (!cfg) return;
    const d = dash.data(cfg.src);
    if (d.status !== 'ok') return wait(el, d.status);
    const all = d.data.filter((r) => r[cfg.field] != null);
    const wrap = document.createElement('div');
    wrap.className = 'bb-facets';
    el.replaceChildren(wrap);
    const tip = makeTip(el);
    const full = Math.floor(wrap.getBoundingClientRect().width) || el.clientWidth || 600, gap = 28;
    const cols = cfg.facets.length > 1 && full >= 2 * 320 + gap ? 2 : 1;
    const fw = Math.floor((full - gap * (cols - 1)) / cols);
    wrap.style.gridTemplateColumns = 'repeat(' + cols + ', minmax(0, 1fr))';
    const sharedMax = d3.max(all, (r) => r[cfg.field]);
    cfg.facets.forEach((model) => {
      const rows = all.filter((r) => r.model === model);
      const groups = ARMS.map((a) => rows.filter((r) => r.arm === a)).filter((g) => g.length);
      if (!groups.length) return;
      const svg = d3.select(wrap).append('svg').attr('class', 'bb-svg').attr('role', 'img').attr('aria-label', cfg.label + ', ' + MODEL[model] + ', by contender');
      const each = (g) => cfg.val ? cfg.val(g) : g.map((r) => cfg.fmt(r[cfg.field])).join(' · ');
      const span = (g) => cfg.val || g.length < 3 ? each(g) : cfg.fmt(d3.min(g, (r) => r[cfg.field])) + ' to ' + cfg.fmt(d3.max(g, (r) => r[cfg.field]));
      const labW = d3.max(groups, (g) => textW(svg, g[0].name));
      const valText = fw - labW - d3.max(groups, (g) => textW(svg, each(g), 'bb-val')) < 200 ? span : each;
      const valW = d3.max(groups, (g) => textW(svg, valText(g), 'bb-val'));
      const m = {t: 28, l: Math.ceil(labW) + 14, r: Math.ceil(valW) + 16, b: 24}, rh = 30;
      const H = m.t + groups.length * rh + m.b;
      svg.attr('viewBox', '0 0 ' + fw + ' ' + H);
      const max = cfg.max || (cfg.shared ? sharedMax : d3.max(rows, (r) => r[cfg.field]));
      const x = d3.scaleLinear().domain([cfg.min || 0, max]).range([m.l, Math.max(m.l + 40, fw - m.r)]);   // only dot charts set a min: a dot's position does not need a zero
      if (!cfg.max) x.nice(4);
      const ticks = x.ticks(Math.max(2, Math.min(5, Math.floor((fw - m.l - m.r) / 64))));
      svg.append('text').attr('class', 'bb-facet').attr('x', 0).attr('y', 14).text(MODEL[model]);
      const gr = svg.append('g');
      gr.selectAll('line').data(ticks).join('line').attr('class', (t) => t === (cfg.min || 0) ? 'bb-axis' : 'bb-grid')
        .attr('x1', (t) => x(t)).attr('x2', (t) => x(t)).attr('y1', m.t - 2).attr('y2', H - m.b + 2);
      gr.selectAll('text').data(ticks).join('text').attr('class', 'bb-tick').attr('text-anchor', 'middle')
        .attr('x', (t) => x(t)).attr('y', H - m.b + 17).text((t) => cfg.tick(t));
      const row = svg.append('g').selectAll('g').data(groups).join('g').attr('transform', (g, i) => 'translate(0,' + (m.t + i * rh) + ')');
      row.append('text').attr('x', 0).attr('y', rh / 2 + 4).text((g) => g[0].name);
      row.each(function (g) {
        const s = d3.select(this), color = FAM[g[0].family] || FAM.Baseline, open = OPEN(g[0].arm), vals = g.map((r) => r[cfg.field]);
        if (cfg.dots) {
          if (vals.length > 1) s.append('line').attr('x1', x(d3.min(vals))).attr('x2', x(d3.max(vals))).attr('y1', rh / 2).attr('y2', rh / 2).style('stroke', color).style('stroke-width', 2).style('opacity', 0.45);
          s.selectAll('circle').data(vals).join('circle').attr('cx', (v) => x(v)).attr('cy', rh / 2).attr('r', (open ? 4.5 : 5.5) - (cfg.many ? 1 : 0)).style('fill', open ? SURFACE : color).style('stroke', open ? color : SURFACE).style('stroke-width', cfg.many ? 1.5 : 2);
          s.append('text').attr('class', 'bb-val').attr('x', fw - m.r + 10).attr('y', rh / 2 + 4).text(valText(g));
        } else {
          s.append('path').attr('d', bar(x(0), x(vals[0]), rh / 2 - 6, 12, 4)).style('fill', color).style('opacity', open ? 0.45 : null);
          s.append('text').attr('class', 'bb-val').attr('x', x(vals[0]) + 7).attr('y', rh / 2 + 4).text(valText(g));
        }
        s.append('rect').attr('class', 'bb-hit').attr('x', 0).attr('y', 0).attr('width', fw).attr('height', rh)
          .on('pointerenter pointermove', (ev) => tip.show(ev, g[0].name + ', ' + MODEL[model], [cfg.label + ': ' + valText(g)].concat(cfg.tip(g))))
          .on('pointerleave', () => tip.hide());
      });
    });
  });

  // the judge's 0 to 3 scores as shares of a contender's sessions: one stacked bar per contender, a facet per model
  dash.draw('stack', (el) => {
    const d = dash.data('single_tasks');
    if (d.status !== 'ok') return wait(el, d.status);
    const wrap = document.createElement('div');
    wrap.className = 'bb-facets';
    el.replaceChildren(wrap);
    const tip = makeTip(el);
    const full = Math.floor(wrap.getBoundingClientRect().width) || el.clientWidth || 600, gap = 28;
    const cols = full >= 2 * 320 + gap ? 2 : 1;
    const fw = Math.floor((full - gap * (cols - 1)) / cols);
    wrap.style.gridTemplateColumns = 'repeat(' + cols + ', minmax(0, 1fr))';
    ['haiku', 'opus'].forEach((model) => {
      const rows = ARMS.map((a) => d.data.find((r) => r.arm === a && r.model === model)).filter((r) => r && r.sessions_judged);
      if (!rows.length) return;
      const svg = d3.select(wrap).append('svg').attr('class', 'bb-svg').attr('role', 'img').attr('aria-label', 'Share of sessions at each over-built score, ' + MODEL[model] + ', by contender');
      const val = (r) => FMT.pct0(r.scored_0_pct) + ' at 0';
      const labW = d3.max(rows, (r) => textW(svg, r.name)), valW = d3.max(rows, (r) => textW(svg, val(r), 'bb-val'));
      const m = {t: 28, l: Math.ceil(labW) + 14, r: Math.ceil(valW) + 16, b: 24}, rh = 30, H = m.t + rows.length * rh + m.b;
      svg.attr('viewBox', '0 0 ' + fw + ' ' + H);
      const x = d3.scaleLinear().domain([0, 100]).range([m.l, Math.max(m.l + 40, fw - m.r)]);
      const ticks = [0, 25, 50, 75, 100];
      svg.append('text').attr('class', 'bb-facet').attr('x', 0).attr('y', 14).text(MODEL[model]);
      const gr = svg.append('g');
      gr.selectAll('line').data(ticks).join('line').attr('class', (t) => t === 0 ? 'bb-axis' : 'bb-grid').attr('x1', (t) => x(t)).attr('x2', (t) => x(t)).attr('y1', m.t - 2).attr('y2', H - m.b + 2);
      gr.selectAll('text').data(ticks).join('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (t) => x(t)).attr('y', H - m.b + 17).text((t) => pctTick(t));
      const row = svg.append('g').selectAll('g').data(rows).join('g').attr('transform', (r, i) => 'translate(0,' + (m.t + i * rh) + ')');
      row.append('text').attr('x', 0).attr('y', rh / 2 + 4).text((r) => r.name);
      row.each(function (r) {
        const s = d3.select(this), color = FAM[r.family] || FAM.Baseline;
        let at = 0;
        [0, 1, 2, 3].forEach((k) => {
          const share = r['scored_' + k + '_pct'];
          if (share > 0) {
            const x0 = x(at) + (at > 0 ? 2 : 0), x1 = x(at + share);
            if (x1 > x0) s.append('rect').attr('x', x0).attr('y', rh / 2 - 6).attr('width', x1 - x0).attr('height', 12).attr('rx', 2).style('fill', color).style('opacity', SCORE_OPACITY[k]);
          }
          at += share;
        });
        s.append('text').attr('class', 'bb-val').attr('x', fw - m.r + 10).attr('y', rh / 2 + 4).text(val(r));
        s.append('rect').attr('class', 'bb-hit').attr('x', 0).attr('y', 0).attr('width', fw).attr('height', rh)
          .on('pointerenter pointermove', (ev) => tip.show(ev, r.name + ', ' + MODEL[model], [0, 1, 2, 3].map((k) => 'Score ' + k + ': ' + r['scored_' + k] + ' of ' + r.sessions_judged + ' sessions (' + FMT.pct0(r['scored_' + k + '_pct']) + ')').concat('Mean score ' + FMT.d2(r.over_engineering) + ' of 3')))
          .on('pointerleave', () => tip.hide());
      });
    });
  });

  // money spent so far after each ticket, four contenders, one model
  const LINE_ARMS = ['baseline', 'ponytail', 'ken', 'bunnyhug-v8'];
  // Haiku, twenty runs each: at every ticket one vertical column of small dots, one per run and coloured by
  // contender, with a larger marker at each contender's average, joined into a line across the tickets
  function drawRuns(el) {
    const means = dash.data('haiku20_tickets'), runs = dash.data('haiku20_steps');
    if (means.status !== 'ok') return wait(el, means.status);
    if (runs.status !== 'ok') return wait(el, runs.status);
    const arms = LINE_ARMS.filter((a) => means.data.some((r) => r.arm === a));
    const steps = Array.from(new Set(means.data.map((r) => r.step))).sort((a, b) => a - b);
    const W = el.clientWidth || 600, H = 360, wide = W >= 560;
    const svg = d3.create('svg').attr('class', 'bb-svg').attr('viewBox', '0 0 ' + W + ' ' + H).attr('role', 'img')
      .attr('aria-label', 'Money spent so far after each of eleven tickets on Haiku: every run and the average, for the baseline, Ponytail, Ken and Bunnyhug v8');
    el.replaceChildren(svg.node());
    const tip = makeTip(el);
    if (!arms.length) return;
    const series = arms.map((a) => means.data.filter((r) => r.arm === a).sort((p, q) => p.step - q.step));
    const cell = (a, k) => runs.data.filter((r) => r.arm === a && r.step === k).map((r) => r.cost_so_far_usd);
    const y = d3.scaleLinear().domain([0, d3.max(runs.data, (r) => r.cost_so_far_usd)]).nice(5), yt = y.ticks(5);
    const endLabel = (s) => s[0].name + '  ' + FMT.usd2(s[s.length - 1].cost_so_far_usd);
    const m = {t: 14, b: 40, l: Math.ceil(d3.max(yt, (t) => textW(svg, usdTick(t), 'bb-tick'))) + 12, r: wide ? Math.ceil(d3.max(series, (s) => textW(svg, endLabel(s)))) + 16 : 14};
    y.range([H - m.b, m.t]);
    const x = d3.scaleBand().domain(steps).range([m.l, W - m.r]).paddingInner(0.2).paddingOuter(0.08);
    const mid = (k) => x(k) + x.bandwidth() / 2;
    const g = svg.append('g');
    g.selectAll('line').data(yt).join('line').attr('class', (t) => t === 0 ? 'bb-axis' : 'bb-grid').attr('x1', m.l).attr('x2', W - m.r).attr('y1', (t) => y(t)).attr('y2', (t) => y(t));
    g.selectAll('text').data(yt).join('text').attr('class', 'bb-tick').attr('text-anchor', 'end').attr('x', m.l - 8).attr('y', (t) => y(t) + 4).text((t) => usdTick(t));
    svg.append('g').selectAll('text').data(steps).join('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (k) => x(k) + x.bandwidth() / 2).attr('y', H - m.b + 17).text((k) => k + 1);
    svg.append('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (m.l + W - m.r) / 2).attr('y', H - 6).text('Ticket');
    const small = 2.4;
    const dots = svg.append('g'), lines = svg.append('g');
    series.forEach((s) => {
      const a = s[0].arm, color = FAM[s[0].family] || FAM.Baseline, open = OPEN(a);
      steps.forEach((k) => {
        dots.append('g').selectAll('circle').data(cell(a, k)).join('circle').attr('cx', mid(k)).attr('cy', (v) => y(v)).attr('r', small)
          .style('fill', open ? SURFACE : color).style('stroke', open ? color : 'none').style('stroke-width', 1).style('opacity', 0.7);
      });
      const line = d3.line().x((r) => mid(r.step)).y((r) => y(r.cost_so_far_usd));
      lines.append('path').attr('d', line(s)).style('fill', 'none').style('stroke', color).style('stroke-width', 2).style('stroke-linejoin', 'round').style('stroke-dasharray', open ? '5 4' : null);
      lines.append('g').selectAll('circle').data(s).join('circle').attr('cx', (r) => mid(r.step)).attr('cy', (r) => y(r.cost_so_far_usd)).attr('r', 4)
        .style('fill', open ? SURFACE : color).style('stroke', open ? color : SURFACE).style('stroke-width', 1.5);
    });
    if (wide) {
      const ends = series.map((s) => ({s: s, y: y(s[s.length - 1].cost_so_far_usd)})).sort((a, b) => a.y - b.y);
      for (let i = 1; i < ends.length; i++) ends[i].y = Math.max(ends[i].y, ends[i - 1].y + 15);
      for (let i = ends.length - 2; i >= 0; i--) ends[i].y = Math.min(ends[i].y, ends[i + 1].y - 15);
      svg.append('g').selectAll('text').data(ends).join('text').attr('x', W - m.r + 10).attr('y', (e) => e.y + 4).text((e) => endLabel(e.s));
    }
    svg.append('g').selectAll('rect').data(steps).join('rect').attr('class', 'bb-hit').attr('x', (k) => x(k) - x.step() * x.paddingInner() / 2).attr('y', m.t).attr('width', x.step()).attr('height', H - m.b - m.t)
      .on('pointerenter pointermove', (ev, k) => {
        const at = series.map((s) => s.find((r) => r.step === k)).filter(Boolean).sort((a, b) => b.cost_so_far_usd - a.cost_so_far_usd);
        if (!at.length) return;
        tip.show(ev, 'Ticket ' + (k + 1) + ', ' + at[0].ticket, at.map((r) => { const v = cell(r.arm, k); return {color: FAM[r.family] || FAM.Baseline,
          text: r.name + ': ' + FMT.usd2(r.cost_so_far_usd) + ' on average, ' + FMT.usd2(d3.min(v)) + ' to ' + FMT.usd2(d3.max(v)) + ' over ' + v.length + ' runs'}; }));
      })
      .on('pointerleave', () => tip.hide());
  }

  dash.draw('lines', (el) => {
    const model = el.dataset.model === 'haiku' ? 'haiku' : 'opus';
    if (model === 'haiku') return drawRuns(el);
    // Haiku is drawn from the twenty-run set
    const d = dash.data(model === 'haiku' ? 'haiku20_tickets' : 'tickets');
    if (d.status !== 'ok') return wait(el, d.status);
    const series = LINE_ARMS.map((a) => d.data.filter((r) => r.arm === a && r.model === model).sort((p, q) => p.step - q.step)).filter((s) => s.length);
    const W = el.clientWidth || 600, H = 320, wide = W >= 560;
    const svg = d3.create('svg').attr('class', 'bb-svg').attr('viewBox', '0 0 ' + W + ' ' + H).attr('role', 'img')
      .attr('aria-label', 'Money spent so far after each of eleven tickets, ' + MODEL[model] + ', for the baseline, Ponytail, Ken and Bunnyhug v8');
    el.replaceChildren(svg.node());
    const tip = makeTip(el);
    if (!series.length) return;
    const max = d3.max(series, (s) => d3.max(s, (r) => r.cost_so_far_usd));
    const y = d3.scaleLinear().domain([0, max]).nice(4);
    const yt = y.ticks(4);
    const endLabel = (s) => s[0].name + '  ' + FMT.usd2(s[s.length - 1].cost_so_far_usd);
    const m = {t: 14, b: 40, l: Math.ceil(d3.max(yt, (t) => textW(svg, usdTick(t), 'bb-tick'))) + 12, r: wide ? Math.ceil(d3.max(series, (s) => textW(svg, endLabel(s)))) + 16 : 14};
    y.range([H - m.b, m.t]);
    const x = d3.scaleLinear().domain([0, 10]).range([m.l, W - m.r]);
    const g = svg.append('g');
    g.selectAll('line').data(yt).join('line').attr('class', (t) => t === 0 ? 'bb-axis' : 'bb-grid').attr('x1', m.l).attr('x2', W - m.r).attr('y1', (t) => y(t)).attr('y2', (t) => y(t));
    g.selectAll('text').data(yt).join('text').attr('class', 'bb-tick').attr('text-anchor', 'end').attr('x', m.l - 8).attr('y', (t) => y(t) + 4).text((t) => usdTick(t));
    const steps = d3.range(11);
    svg.append('g').selectAll('text').data(steps).join('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (s) => x(s)).attr('y', H - m.b + 17).text((s) => s + 1);
    svg.append('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (m.l + W - m.r) / 2).attr('y', H - 6).text('Ticket');
    const cross = svg.append('line').attr('class', 'bb-axis').attr('y1', m.t).attr('y2', H - m.b).style('display', 'none');
    const line = d3.line().x((r) => x(r.step)).y((r) => y(r.cost_so_far_usd));
    const col = (s) => FAM[s[0].family] || FAM.Baseline;
    svg.append('g').selectAll('path').data(series).join('path').attr('d', line).style('fill', 'none').style('stroke', col).style('stroke-width', 2).style('stroke-linejoin', 'round').style('stroke-dasharray', (s) => OPEN(s[0].arm) ? '5 4' : null);
    series.forEach((s) => {
      svg.append('g').selectAll('circle').data(s).join('circle').attr('cx', (r) => x(r.step)).attr('cy', (r) => y(r.cost_so_far_usd)).attr('r', 3.5)
        .style('fill', OPEN(s[0].arm) ? SURFACE : col(s)).style('stroke', OPEN(s[0].arm) ? col(s) : SURFACE).style('stroke-width', 1.5);
    });
    if (wide) {
      const ends = series.map((s) => ({s: s, y: y(s[s.length - 1].cost_so_far_usd)})).sort((a, b) => a.y - b.y);
      for (let i = 1; i < ends.length; i++) ends[i].y = Math.max(ends[i].y, ends[i - 1].y + 15);
      for (let i = ends.length - 2; i >= 0; i--) ends[i].y = Math.min(ends[i].y, ends[i + 1].y - 15);
      svg.append('g').selectAll('text').data(ends).join('text').attr('x', (e) => x(e.s[e.s.length - 1].step) + 10).attr('y', (e) => e.y + 4).text((e) => endLabel(e.s));
    }
    svg.append('rect').attr('class', 'bb-hit').attr('x', m.l - 6).attr('y', m.t).attr('width', Math.max(0, W - m.r - m.l + 12)).attr('height', H - m.b - m.t)
      .on('pointerenter pointermove', (ev) => {
        const px = d3.pointer(ev, svg.node())[0];
        const step = Math.max(0, Math.min(10, Math.round(x.invert(px))));
        cross.attr('x1', x(step)).attr('x2', x(step)).style('display', null);
        const at = series.map((s) => s.find((r) => r.step === step)).filter(Boolean).sort((a, b) => b.cost_so_far_usd - a.cost_so_far_usd);
        if (!at.length) return;
        tip.show(ev, 'Ticket ' + (step + 1) + ', ' + at[0].ticket, at.map((r) => ({color: FAM[r.family] || FAM.Baseline, text: r.name + ': ' + FMT.usd2(r.cost_so_far_usd) + ' so far'})));
      })
      .on('pointerleave', () => { cross.style('display', 'none'); tip.hide(); });
  });

  // cost of a run against the files holding its rules: one dot per run, a facet per model
    dash.draw('trade', (el) => {
    const d = dash.data('sequences'), h = dash.data('haiku20');
    if (d.status !== 'ok') return wait(el, d.status);
    if (h.status !== 'ok') return wait(el, h.status);
    // Opus from the original runs; Haiku from the twenty-run set
    const all = d.data.filter((r) => r.model === 'opus').concat(h.data).filter((r) => r.rule_files != null && r.cost_usd != null);
    const wrap = document.createElement('div');
    wrap.className = 'bb-facets';
    el.replaceChildren(wrap);
    const tip = makeTip(el);
    const full = Math.floor(wrap.getBoundingClientRect().width) || el.clientWidth || 600, gap = 28;
    const cols = full >= 2 * 320 + gap ? 2 : 1;
    const fw = Math.floor((full - gap * (cols - 1)) / cols), H = 320;
    wrap.style.gridTemplateColumns = 'repeat(' + cols + ', minmax(0, 1fr))';
    const yMax = d3.max(all, (r) => r.rule_files);
    ['haiku', 'opus'].forEach((model) => {
      const rows = all.filter((r) => r.model === model);
      if (!rows.length) return;
      const svg = d3.select(wrap).append('svg').attr('class', 'bb-svg').attr('viewBox', '0 0 ' + fw + ' ' + H).attr('role', 'img')
        .attr('aria-label', 'Cost of each run against the number of files holding its five rules, ' + MODEL[model]);
      const y = d3.scaleLinear().domain([0, yMax]).nice(4), yt = y.ticks(4);
      const m = {t: 50, r: 18, b: 42, l: Math.ceil(d3.max(yt, (t) => textW(svg, String(t), 'bb-tick'))) + 12};
      y.range([H - m.b, m.t]);
      const x = d3.scaleLinear().domain([0, d3.max(rows, (r) => r.cost_usd)]).nice(4).range([m.l, fw - m.r]);
      const xt = x.ticks(Math.max(2, Math.min(6, Math.floor((fw - m.l - m.r) / 70))));
      svg.append('text').attr('class', 'bb-facet').attr('x', 0).attr('y', 14).text(MODEL[model]);
      svg.append('text').attr('class', 'bb-tick').attr('x', 0).attr('y', 34).text('Files holding the five rules');
      const g = svg.append('g');
      g.selectAll('line.h').data(yt).join('line').attr('class', (t) => t === 0 ? 'bb-axis' : 'bb-grid').attr('x1', m.l).attr('x2', fw - m.r).attr('y1', (t) => y(t)).attr('y2', (t) => y(t));
      g.selectAll('text.h').data(yt).join('text').attr('class', 'bb-tick').attr('text-anchor', 'end').attr('x', m.l - 8).attr('y', (t) => y(t) + 4).text((t) => t);
      g.selectAll('line.v').data(xt.filter((t) => t !== 0)).join('line').attr('class', 'bb-grid').attr('x1', (t) => x(t)).attr('x2', (t) => x(t)).attr('y1', m.t).attr('y2', H - m.b);
      svg.append('g').selectAll('text').data(xt).join('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (t) => x(t)).attr('y', H - m.b + 17).text((t) => usdTick(t));
      svg.append('text').attr('class', 'bb-tick').attr('text-anchor', 'middle').attr('x', (m.l + fw - m.r) / 2).attr('y', H - 6).text('Cost of the run');
      const dot = svg.append('g').selectAll('g').data(rows).join('g').attr('transform', (r) => 'translate(' + x(r.cost_usd) + ',' + y(r.rule_files) + ')');
      const small = rows.length > 20 ? 1.5 : 0;
      dot.append('circle').attr('r', (r) => (OPEN(r.arm) ? 4.5 : 5.5) - small).style('fill', (r) => OPEN(r.arm) ? SURFACE : FAM[r.family] || FAM.Baseline).style('stroke', (r) => OPEN(r.arm) ? FAM[r.family] : SURFACE).style('stroke-width', small ? 1.5 : 2);
      dot.append('circle').attr('class', 'bb-hit').attr('r', small ? 7 : 13)
        .on('pointerenter pointermove', (ev, r) => tip.show(ev, r.name + ', ' + MODEL[model] + ', run ' + (r.seq + 1), [FMT.usd2(r.cost_usd) + ' for the run', r.rule_files + ' files hold the five rules', FMT.int(r.source_lines) + ' source lines']))
        .on('pointerleave', () => tip.hide());
    });
  });


  // a key above the charts whose marks are not labelled one by one
  const CONTENDERS = [['Bunnyhug', 'Bunnyhug v8'], ['Ponytail', 'Ponytail'], ['Ken', 'Ken'], ['Baseline', 'Baseline (no skill)']].map(([fam, label]) => ({label: label, color: FAM[fam]}));
  const KEYS = {lines: CONTENDERS, trade: CONTENDERS,
    stack: ['0: minimal', '1: slightly more structure than needed', '2: noticeably over-built', '3: clearly over-engineered'].map((label, k) => ({label: label, color: 'currentColor', opacity: SCORE_OPACITY[k]}))};
  function key(items) {
    const ul = document.createElement('ul');
    ul.className = 'bb-keys';
    items.forEach((it) => {
      const li = document.createElement('li'), sw = document.createElement('i');
      li.className = 'bb-key'; sw.className = 'bb-sw';
      sw.style.background = it.color;
      if (it.opacity) { sw.style.opacity = it.opacity; sw.style.borderRadius = '2px'; }
      li.append(sw, it.label);
      ul.appendChild(li);
    });
    return ul;
  }
  function run() {
    document.querySelectorAll('.bb-chart[data-draw]').forEach((host) => {
      const fn = draws[host.dataset.draw];
      if (!fn) return;
      const plot = document.createElement('div');
      plot.className = 'bb-plot';
      if (host.dataset.chart) plot.dataset.chart = host.dataset.chart;
      if (host.dataset.model) plot.dataset.model = host.dataset.model;
      host.replaceChildren(...(KEYS[host.dataset.draw] ? [key(KEYS[host.dataset.draw])] : []), plot);
      fn(plot);
    });
  }
  let width = 0;
  window.addEventListener('resize', () => {     // a phone fires this on every scroll; only a new width needs a redraw
    if (document.documentElement.clientWidth === width) return;
    width = document.documentElement.clientWidth;
    run();
  });
  // labels are measured to lay a chart out, so wait for the page's fonts as well as the numbers
  Promise.all([fetch(new URL('data.json', HERE)).then((r) => r.json()), document.fonts ? document.fonts.ready : null])
    .then(([d]) => { DATA = d; }, () => { DATA = {}; })
    .then(() => { width = document.documentElement.clientWidth; run(); });
})();
